#include <bits/stdc++.h>
using namespace std;

int findContentChildren(vector<int>& g, vector<int>& s) {
    sort(g.begin(), g.end());
    sort(s.begin(), s.end());
    int child = 0;
    for (int i = 0; i < (int)s.size() && child < (int)g.size(); ++i)
        if (s[i] >= g[child]) ++child;
    return child;
}

