import java.util.Arrays;

class Solution {
    public int findContentChildren(int[] g, int[] s) {
        Arrays.sort(g);
        Arrays.sort(s);
        int child = 0;
        for (int token : s) {
            if (child < g.length && token >= g[child]) ++child;
        }
        return child;
    }
}
